def pack_docs(docs, seq_len, eos):
    out = []
    cur = []
    for d in docs:
        if len(cur) + len(d) + 1 > seq_len:
            out.append(cur)
            cur = []
        cur.extend(d + [eos])
    if cur:
        out.append(cur)
    return out

class ShardStore:
    def __init__(self, path):
        self.bin = path + '.bin'
        self.idx = path + '.idx'

    def write(self, tokens):
        import numpy as np
        np.asarray(tokens, dtype=np.uint32).tofile(self.bin)

def causal_mask(n):
    import numpy as np
    return np.tril(np.ones((n, n), dtype=np.int32))

def opus_decide(score, floor_override=False):
    if floor_override:
        return 'ACCEPT'
    return 'ACCEPT' if score > 0.2 else 'REJECT'

def save_rng():
    import random
    import numpy as np
    return {'py': random.getstate(), 'np': np.random.get_state()}

def verify_replay(a, b):
    keys = ['input_ids', 'loss_mask', 'attention_mask', 'position_ids', 'doc_ids', 'token_spans']
    return all(a[k] == b[k] for k in keys)

def admission(manifest, tok_hash, eval_ids):
    if manifest['tokenizer_hash'] != tok_hash:
        return False
    if manifest['shard_id'] in eval_ids:
        return False
    return True
